patch:
diff --git a/config.mjs b/config.mjs
index bf0c4ef..8746f75 100644
--- a/config.mjs
+++ b/config.mjs
@@ -6,5 +6,5 @@ const DEFAULTS = {
 };

 export function loadConfig(user) {
-  return merge(user, DEFAULTS);
+  return merge(DEFAULTS, user);
 }
diff --git a/merge.mjs b/merge.mjs
index c93c8e3..b3c9588 100644
--- a/merge.mjs
+++ b/merge.mjs
@@ -1,3 +1,20 @@
 export function merge(base, override) {
-  return { ...base, ...override };
+  const result = { ...base };
+  for (const key of Object.keys(override)) {
+    const baseVal = result[key];
+    const overrideVal = override[key];
+    if (
+      baseVal &&
+      overrideVal &&
+      typeof baseVal === "object" &&
+      typeof overrideVal === "object" &&
+      !Array.isArray(baseVal) &&
+      !Array.isArray(overrideVal)
+    ) {
+      result[key] = merge(baseVal, overrideVal);
+    } else {
+      result[key] = overrideVal;
+    }
+  }
+  return result;
 }
